import sharp from 'sharp';
const mask = Buffer.from('<svg xmlns="http://www.w3.org/2000/svg" width="800" height="800"><rect width="800" height="800" rx="96" fill="white"/></svg>');
await sharp('input.jpg').resize(800, 800).composite([{ input: mask, blend: 'dest-in' }]).png().toFile('output.png');

import sharp from 'sharp';
const logo = await sharp('logo.png').resize({ width: 180 }).png().toBuffer();
await sharp('input.jpg').composite([{ input: logo, gravity: 'southeast', blend: 'over' }]).png().toFile('output.png');

import sharp from 'sharp';
const base = await sharp('input.jpg').rotate().png().toBuffer();
const { width, height } = await sharp(base).metadata();
const texture = await sharp('texture.png').resize(width, height, { fit: 'cover' }).png().toBuffer();
await sharp(base).composite([{ input: texture, blend: 'multiply' }]).png().toFile('output.png');
